  "arena.scenarios.bat_beg_01.s1_opt_2": "የኔትወርክ ፓኬት ፍሰት።",
  "arena.scenarios.bat_beg_01.s1_question": "Invoice_October_Statement.exe የተሰኘው ፋይል ምን አይነት አደጋ አለው?",
  "arena.scenarios.bat_beg_01.s1_title": "የተላከውን መልዕክት ይመርምሩ",
