  "c.pdf_blocked_fallback": "አሳሹ ትሩን እንዳይከፍት አግዶታል። እባክዎ ብቅ-ባይን ይፍቀዱ ወይም 'አትም / በፒዲኤፍ አስቀምጥ'ን ይጠቀሙ።",
  "c.pdf_download_err": "ፒዲኤፍ ማውረድ አልተቻለም። እባክዎ 'ፒዲኤፍ ክፈት' ወይም 'አትም / በፒዲኤፍ አስቀምጥ' ይጠቀሙ።",
  "c.pdf_generated": "የክስተቱ ሪፖርት ፒዲኤፍ ተዘጋጅቶ ወርዷል።",
