  "journey.continue_mission": "ተልዕኮውን ቀጥል",
  "journey.debrief.cta_m1": "ሊንኩን በM1 ይመርምሩ",
  "journey.debrief.cta_m2": "የ M2 የይለፍ ቃል ደህንነት መሣሪያን ክፈት",
  "journey.debrief.cta_m3": "ሪፖርቱን በM3 ያዘጋጁ",
  "journey.debrief.rule1": "1. የማስጠንቀቂያ ምልክቶች እንደ ጠቋሚ፡ እጅግ የበዛ አስቸኳይነት፣ ካልታወቀ ላኪ የተላከ መልእክት፣ የቅድመ ክፍያ ጥያቄ እና አጠራጣሪ ሊንኮች ቁልፍ የማስጠንቀቂያ ምልክቶች ናቸው እንጂ በራሳቸው ፍጹም ማረጋገጫ አይደሉም። አጠቃላይ ሁኔታውን ያመዛዝኑ።",
  "journey.debrief.rule2": "2. የጎራ ስም ጥንቃቄ፦ ይፋዊ የኢትዮጵያ ተቋማት በአብዛኛው \".edu.et\" ወይም \".gov.et\" ቢጠቀሙም፣ የጎራው መጨረሻ ብቻውን ፍጹም ደህንነትን አያረጋግጥም። በተመሳሳይ እንደ \".top\"፣ \".xyz\" ወይም \".cc\" ያሉ ጎራዎች በራሳቸው አደገኛ ናቸው ማለት አይደለም። ሁልጊዜ ተቋሙን በታመኑ ይፋዊ መንገዶች ያረጋግጡ።",
  "journey.debrief.rule3": "3. ከተቋማት በተናጠል ማረጋገጥ፦ በመለያ ስማቸው ላይ \"_Official\" ወይም ባጅ ስላላቸው ብቻ አትመኑ። ገንዘብ ወይም መረጃ ከመስጠትዎ በፊት ስኮላርሺፑን ከዩኒቨርሲቲው ወይም ከትምህርት ሚኒስቴር በቀጥታ ያረጋግጡ።",
  "journey.debrief.title": "የተልዕኮ ትንተና እና የሳይበር ደህንነት መርሆዎች",
  "journey.decision.desc": "ሱፊያንን ከማጭበርበር እና ከመረጃ ስርቆት ለመጠበቅ በጣም አስተማማኝ የሆነውን የሳይበር መከላከያ እርምጃ ይምረጡ።",
  "journey.decision.execute_btn": "⚡ የመከላከያ እርምጃውን ተግባራዊ አድርግ",
  "journey.decision.title": "ሱፊያን ምን ማድረግ አለበት?",
