  "journey.p11.evidence.night_desc": "አጭበርባሪዎች ተጎጂዎች ምላሽ እንዳይሰጡ ለማድረግ ዘግይቶ የሚደረግ የሌሊት ሰዓትን ይመርጣሉ።",
  "journey.p11.evidence.night_title": "ያልተለመደ የሌሊት ሰዓት",
  "journey.p11.evidence.risk_desc": "መለያው በአስቸኳይ ካልታገደ የቀረው ገንዘብም ሙሉ በሙሉ ሊወሰድ ይችላል።",
  "journey.p11.evidence.risk_title": "የቀሪ ሂሳብ አደጋ",
  "journey.p11.outcome.defeat_delete_app": "መተግበሪያውን ማጥፋት የባንክ ሂሳቡን አያግደውም፤ አጥቂው ከሌላ ቦታ ገንዘብ ማውጣቱን ይቀጥላል።",
  "journey.p11.outcome.defeat_search_telegram": "በቴሌግራም ላይ ያሉ \"ገንዘብ አስመላሽ ቦቶች\" ቀሪውን ገንዘብ ለመስረቅ የተዘጋጁ የውሸት ወጥመዶች ናቸው።",
  "journey.p11.outcome.defeat_wait_morning": "መዘግየት አጥቂዎች የቀረውን ገንዘብ እንዲወስዱ እና ማስረጃዎችን እንዲያጠፉ ጊዜ ይሰጣቸዋል።",
  "journey.p11.outcome.victory_desc": "ፈጣን እና ወሳኝ የአደጋ መከላከያ እርምጃ! መለያውን ወዲያውኑ ማገድ ተጨማሪ ገንዘብ እንዳይወጣ ያቆማል፤ የግብይቱን ቁጥር መያዝ ደግሞ አቤቱታ ለማቅረብ ይረዳል።",
  "journey.p11.simulated_sender": "የክፍያ ስርዓት ማስጠንቀቂያ (የተመሰለ)",
  "journey.p11.story": "ከሌሊቱ 7:30 ላይ ከሞባይል ክፍያዎ እውነተኛ የSMS መልዕክት ደረሰዎት፦ \"ተረጋግጧል፦ 1,800 ብር ወደ Merchant_AutoPay_99 ተላልፏል። ቀሪ ሂሳብዎ 240 ብር ነው።\" እርስዎ ተኝተዋል፤ ምንም አይነት የገንዘብ ዝውውር አላደረጉም።",
  "journey.p11.subtitle": "ያልተፈቀደ የገንዘብ ቅነሳ ሲያጋጥም ፈጣን እና ትክክለኛ የአደጋ መከላከያ እርምጃዎችን ይውሰዱ።",
  "journey.p11.title": "ልምምድ 11: የእኩለ ሌሊት ያልተፈቀደ የገንዘብ ዝውውር",
  "journey.p12.artwork_alt": "አደገኛ የአንድሮይድ ፍቃድን መከልከል እና ተንኮል አዘል መተግበሪያን ማጥፋትን የሚያሳይ ምስል",
  "journey.p12.briefing_label": "አደገኛ የአንድሮይድ ፍቃድ ጥቃት",
  "journey.p12.choice.deny_uninstall": "ፍቃዱን ወዲያውኑ መከልከል፣ መተግበሪያውን ከስልክ ላይ ማጥፋት እና የደህንነት ፍተሻ ማድረግ።",
  "journey.p12.choice.grant_permission": "ማፋጠኛው እንዲሰራ የተደራሽነት ፍቃዱን መስጠት።",
  "journey.p12.choice.grant_temporary": "ቴሌግራምን እንደሚያፈጥን ለማየት ለ5 ደቂቃ ብቻ ፍቃዱን መስጠት።",
  "journey.p12.choice.share_channel": "መተግበሪያውን ለሌሎች ተማሪዎች ግሩፕ አጋርቶ ማንም እንደተጠቀመው መጠየቅ።",
  "journey.p12.debrief.rule1": "ካልተረጋገጡ ቦታዎች ለወረዱ መተግበሪያዎች የአንድሮይድ ተደራሽነት አገልግሎት (Accessibility) ፍቃድን በፍጹም አትስጡ።",
  "journey.p12.debrief.rule2": "የተደራሽነት ፍቃድ መተግበሪያው ስክሪንዎን እንዲያይ፣ ሚስጥር ኮዶችን እንዲሰርቅ እና ያለ እርስዎ ፈቃድ እርምጃ እንዲወስድ ያስችለዋል።",
  "journey.p12.debrief.rule3": "ቀላል አገልግሎት እየሰጠ ከፍተኛ የስልክ አስተዳዳሪ ወይም የተደራሽነት ፍቃድ የሚጠይቅ ማንኛውንም መተግበሪያ ወዲያውኑ አጥፉ።",
  "journey.p12.decision.desc": "መተግበሪያ የአንድሮይድ ተደራሽነት አገልግሎት (Accessibility) ፍቃድ ሲጠይቅ አስተማማኙን እርምጃ ይምረጡ።",
  "journey.p12.decision.title": "ስልታዊ ውሳኔ፦ ከፍተኛ አደጋ ያለው የፍቃድ ጥያቄ",
  "journey.p12.evidence.accessibility_desc": "ይህ ፍቃድ መተግበሪያው የስክሪን ላይ ሚስጥሮችን እንዲያነብ፣ የይለፍ ቃላትን እንዲሰርቅ እና ሳያውቁት ቁልፎችን እንዲጫን ያስችለዋል።",
  "journey.p12.evidence.accessibility_title": "የተደራሽነት ፍቃድ ከፍተኛ አደጋ",
  "journey.p12.evidence.origin_desc": "መተግበሪያው የወረደው ካልታወቀ ቻናል በመሆኑ ምንም አይነት የደህንነት ፍተሻ አላለፈም።",
  "journey.p12.evidence.origin_title": "ያልታወቀ ምንጭ",
  "journey.p12.evidence.permission_desc": "ቀላል ማፋጠኛ ወይም ማሳመሪያ መተግበሪያ የስልኩን አጠቃላይ ስክሪን የሚቆጣጠር ፍቃድ በፍጹም አያስፈልገውም።",
  "journey.p12.evidence.permission_title": "ያልተመጣጠነ ፍቃድ",
  "journey.p12.outcome.defeat_grant_permission": "ይህን ፍቃድ መስጠት አጥቂው የባንክ ሚስጥር ቁጥርዎን እንዲሰርቅ፣ የSMS ኮዶችን እንዲያይ እና ያለ እርስዎ እውቀት ገንዘብ እንዲያስተላልፍ ያስችለዋል።",
  "journey.p12.outcome.defeat_grant_temporary": "ተንኮል አዘል መተግበሪያዎች በሰከንዶች ውስጥ የይለፍ ቃላትን እና የግል መረጃዎችን ሰርቀው ይጨርሳሉ።",
  "journey.p12.outcome.defeat_share_channel": "ያልተረጋገጡ የAPK ፋይሎችን ማጋራት የጓደኞችዎ ስልክም በተመሳሳይ ቫይረስ እንዲጠቃ ያደርጋል።",
  "journey.p12.outcome.victory_desc": "ድንቅ ጥበቃ! የተደራሽነት ፍቃድ ጥቃት የባንክ መረጃዎችን ለመስረቅ ዋነኛው የአጥቂዎች መሳሪያ ነው። ወዲያውኑ መከልከል እና ማጥፋት ስልክዎን ሙሉ በሙሉ ይታደጋል።",
  "journey.p12.simulated_sender": "የወረደ መተግበሪያ፦ \"TG_SuperSpeed_Booster.apk\" (የተመሰለ)",
  "journey.p12.story": "ካልተረጋገጠ የቴሌግራም ቻናል \"TG_SuperSpeed_Booster.apk\" የሚል መተግበሪያ አውርደው ጫኑ። ሲከፍቱት፦ \"ማፋጠኛውን ለማስጀመር በአንድሮይድ ማስተካከያ ውስጥ የተደራሽነት አገልግሎትን (Accessibility Service) ፍቀድ\" የሚል ጥያቄ አመጣ።",
  "journey.p12.subtitle": "ስልክዎን አደገኛ የተደራሽነት ፍቃድ ከሚጠይቁ የተጭበረበሩ የAPK መተግበሪያዎች ይጠብቁ።",
  "journey.p12.title": "ልምምድ 12: የአንድሮይድ ተደራሽነት አገልግሎት (Accessibility) ወጥመድ",
  "journey.persistence_disclaimer": "🔒 አካባቢያዊ ሂደት፡ በብሮውዘር ማከማቻ ውስጥ ይቀመጣል። የእርስዎ XP፣ ባጆች እና የተጠናቀቁ ተልዕኮዎች ገጹ ሲታደስ ወይም ብሮውዘሩ ሲዘጋ አይጠፉም፤ የብሮውዘር ዳታ ሲጸዳ ብቻ ዳግም ይጀምራሉ።",
  "journey.practice.artwork_alt": "የወደፊት የሳይበር ጨዋታ ስዕል፡ የመከላከያ ሁኔታዎችን የሚያስመስል ከመስመር ውጭ አዳፕቲቭ የሥልጠና ማትሪክስ",
