  "m1.cti_status_unavailable_desc": "የመስመር ላይ የአደጋ መረጃ አገልግሎቱን ማግኘት አልተቻለም። የአካባቢው የሂውሪስቲክ ምርመራ ሙሉ በሙሉ ተጠብቆ ቀርቧል።",
