  "m1.ml_confidence_label": "የስታቲስቲክስ እርግጠኝነት",
  "m1.ml_confidence_uncalibrated": "ያልተስተካከለ (አልተረጋገጠም)",
  "m1.ml_disclaimer": "በተለየ የUCI PhiUSIIL ቤንችማርክ ዳታሴት ላይ የተገመገመ (በ200 የሙከራ ናሙናዎች ላይ 92.5% ትክክለኛነት)። የሶፍትማክስ ውጤቱ ያልተስተካከለ የቃላት ሞዴል ነጥብ እንጂ የእውነተኛ ዓለም የተረጋገጠ ፕሮባቢሊቲ አይደለም። የቤንችማርክ ትክክለኛነት የዳታሴት ውጤት እንጂ ለአንድ የተለየ ሊንክ ዋስትና አይደለም።",
