  "m2.practice.desc": "ግንዛቤዎን ለመፈተሽ እና በሳይበር ጀግና ጉዞ ውስጥ የልምድ ነጥብ (XP) ለማግኘት ይህን ልምምድ ያጠናቅቁ። (ልብ ወለድ ምሳሌን ብቻ ይጠቀማል)።",
  "m2.practice.feedback_correct": "ትክክል ነው! የይለፍ ቃልን በተለያዩ ቦታዎች ደጋግሞ መጠቀም አንዱ ድረ-ገጽ ሲጠቃ ሌሎች ዋና ዋና መለያዎችዎም በቀላሉ እንዲጠለፉ ያደርጋል። ሁልጊዜ ለእያንዳንዱ መለያ የተለየ የይለፍ ቃል ይጠቀሙ እና MFA ን ያንቁ።",
