  "m2.practice.opt_a": "ምንም አደጋ የለም፣ ምክንያቱም የባንክ ሥርዓቶች የተጣሱ የይለፍ ቃላትን ራሳቸው ወዲያውኑ ስለሚያውቁ።",
  "m2.practice.opt_b": "አጥቂዎች የወጡ የይለፍ ቃላትን በባንክ እና በቴሌኮም አገልግሎቶች ላይ በራስ-ሰር ሞክረው መለያዎችን ስለሚዘርፉ (Credential Stuffing)፤ እያንዳንዱ አገልግሎት የተለየ የይለፍ ቃል ያስፈልገዋል።",
