  "m4.artwork_alt": "የዘመናዊ ሳይበር ምልክት፦ የM4 ድረ-ገጽ ፍተሻ የቴሌሜትሪ ስካነር እና አስመሳይ ውጤቶች",
  "m4.auth": "እውነተኛ ድረ-ገጽን ለመፈተሽ ግልጽ ፈቃድ ያስፈልጋል፤ በዚህ ስሪት አይሰጥም።",
  "m4.chk.CHK-01": "የTLS ሰርተፍኬት",
  "m4.chk.CHK-02": "ከHTTP ወደ HTTPS መዞር",
  "m4.chk.CHK-03": "Strict-Transport-Security ራስጌ",
  "m4.chk.CHK-04": "Content-Security-Policy ራስጌ",
  "m4.chk.CHK-05": "ሌሎች የአሳሽ መከላከያ ራስጌዎች",
  "m4.chk.CHK-06": "የኩኪ ባህሪያት",
  "m4.chk.CHK-07": "ስሪት የሚያሳዩ ራስጌዎች",
  "m4.desc": "M4 አስቀድመው የተዘጋጁ የማስመሰያ የደህንነት ውጤቶችን የሚያሳይ የትምህርት መድረክ እንጂ የቀጥታ ድረ-ገጾችን መፈተሻ አይደለም። ብጁ የድረ-ገጽ አድራሻን አይቀበልም ወይም የውጭ ድረ-ገጾችን አይገናኝም።",
  "m4.distinction": "የደረሰዎትን አገናኝ መፈተሽ ይፈልጋሉ? የአገናኝ ጽሑፍን ለመተንተን M1 Link Checkerን ይጠቀሙ። M4 ድረ-ገጾች እንዴት እንደሚጠበቁ ለመማር ብቻ የተዘጋጀ ነው።",
  "m4.exp.CHK-01": "ትክክለኛ ሰርተፍኬት አሳሾች ድረ-ገጹን እንዲያረጋግጡ ይረዳል። መከላከያ፦ ሰርተፍኬቱን ከመጠናቀቁ በፊት ያድሱ፤ እድሳቱን በራስ-ሰር ያድርጉ።",
  "m4.exp.CHK-02": "የHTTP ጎብኚዎች ወደ HTTPS መዞር አለባቸው። መከላከያ፦ ሁሉንም የHTTP ትራፊክ ወደ HTTPS ያዙሩ።",
  "m4.exp.CHK-03": "HSTS አሳሾች ሁልጊዜ HTTPS እንዲጠቀሙ ይነግራል። መከላከያ፦ ራስጌውን ተስማሚ max-age ጋር ይላኩ።",
  "m4.exp.CHK-04": "CSP ስክሪፕቶች ከየት ሊጫኑ እንደሚችሉ ይገድባል። መከላከያ፦ ጥብቅ ፖሊሲ ይግለጹ።",
  "m4.exp.CHK-05": "እንደ X-Content-Type-Options፣ Referrer-Policy እና Permissions-Policy ያሉ ራስጌዎች ጥበቃ ይጨምራሉ። መከላከያ፦ እያንዳንዱን ሆን ብለው ያዋቅሩ።",
  "m4.exp.CHK-06": "Secure፣ HttpOnly እና SameSite ባንዲራዎች የሴሽን ኩኪዎችን ይጠብቃሉ። መከላከያ፦ ሦስቱንም ያዋቅሩ።",
  "m4.exp.CHK-07": "Server ወይም X-Powered-By እሴቶች የሶፍትዌር ስሪቶችን ያሳያሉ። መከላከያ፦ ያስወግዷቸው ወይም ይቀንሱ።",
  "m4.fix": "ምን ማድረግ ይገባል",
  "m4.instruction": "የTLS ሰርተፍኬት፣ የHTTPS ማዞሪያ፣ HSTS፣ CSP፣ የደህንነት ራስጌዎች፣ የኩኪ ባህሪያት እና የስሪት መገለጥ ማስመሰያ ውጤቶችን ለመመልከት ከታች ካሉት DS-A፣ DS-B ወይም DS-C አንዱን ይምረጡ።",
  "m4.mode": "ሁኔታ፦ ማሳያ (የተመሰለ፣ ያለ ኢንተርኔት)። የቀጥታ ሁኔታ በዚህ ስሪት አይገኝም።",
