  "digital_city.equipment.network_pulse.desc": "በአቅራቢያ ያሉ ጠላቶችን የሚያደናግጥ እና ወደ ኋላ የሚገፈትር ሞገድ።",
  "digital_city.equipment.security_drone.name": "የጥበቃ ድሮን (Sentinel Drone)",
  "digital_city.equipment.security_drone.desc": "በራስ ገዝ የሚበር እና በጠላት ላይ ተኩስ የሚከፍት አጋዥ ድሮን።",
  "digital_city.equipment.recovery_beacon.name": "የዳግም ማግኛ ምሰሶ (Recovery Beacon)",
  "digital_city.equipment.recovery_beacon.desc": "የተጎዱ ሰርቨሮችን እና የጋሻ ጉልበትን የሚያድስ ተከላ።",
  "digital_city.equipment.signal_scanner.name": "የሲግናል መመርመሪያ (Signal Scanner)",
  "digital_city.equipment.signal_scanner.desc": "የተደበቁ ጠላቶችን እና የስርዓት ክፍተቶችን የሚያጋልጥ መፈለጊያ።",
  "digital_city.equipment.encryption_barrier.name": "የኢንክሪፕሽን አጥር (Encryption Barrier)",
  "digital_city.equipment.encryption_barrier.desc": "መሰረተ ልማቶችን ከጠላት ጥቃት የሚከላከል ጠንካራ አጥር።",
  "digital_city.equipment.emp_device.name": "የEMP መከላከያ መሳሪያ",
  "digital_city.equipment.emp_device.desc": "የጠላት ድሮኖችን እና ልዩ መሳሪያዎችን የሚያፈነዳ ኤሌክትሮማግኔቲክ ፍንዳታ።",
  "digital_city.tutorial.step1": "እንኳን ደህና መጡ፣ የሳይበር ጠባቂ። ዲጂታል ከተማ በከባድ ጥቃት ስር ናት። እርስዎ የፊት መስመር ተከላካይ ነዎት።",
  "digital_city.tutorial.step2": "እንቅስቃሴ፡ በከተማው ጎዳናዎች ለመንቀሳቀስ [W]፣ [A]፣ [S] እና [D] ቁልፎችን ይጠቀሙ።",
  "digital_city.tutorial.step3": "ካሜራ እና አነጣጣሪ፡ ፎቆችን ለመቃኘት እና ለማነጣጠር ማውስዎን ያንቀሳቅሱ።",
  "digital_city.tutorial.step4": "ፍጥነት፡ ለመሮጥ [Shift]ን ይጫኑ፣ አጥር ለመዝለል ደግሞ [Space]ን ይጠቀሙ።",
  "digital_city.tutorial.step5": "አደጋን ማጥፋት፡ በተንኮል አዘል ማልዌሮች ላይ ለመተኮስ የግራ ማውስ ክሊክን ይጠቀሙ።",
  "digital_city.tutorial.step6": "የፋየርዎል መከላከያ፡ የጠላት ተኩስ ለመከላከል የቀኝ ማውስ ክሊክን ተጭነው ይያዙ።",
  "digital_city.tutorial.step7": "ታክቲካዊ ሞገድ፡ ጠላት ሲከብብዎት የኔትወርክ ሞገድ ለመልቀቅ [Q]ን ይጫኑ።",
  "digital_city.tutorial.step8": "ስርዓትን ማዳን፡ የተጎዱ ሰርቨሮችን ለማደስ [E]ን በመጫን የማግኛ ምሰሶ ይትከሉ።",
  "digital_city.tutorial.step9": "የቡድን ታክቲክ፡ የጥበቃ ቡድኑን ለማዘዝ [F1]-[F4]ን ይጠቀሙ (ተከተሉኝ፣ ጠብቁ፣ ምቱ፣ ተሰባሰቡ)።",
  "digital_city.tutorial.step10": "ራዳር፡ ጠላቶችን በደማቅ ቀይ እና የተልዕኮ ቦታዎችን በወርቃማ ምልክት በራዳሩ ላይ ይከታተሉ።",
  "digital_city.tutorial.step11": "ዝግጁነት ተረጋግጧል፡ ወደ ውጊያው ለመግባት ሙሉ ፈቃድ አግኝተዋል። ዲጂታል ከተማን ይታደጉ!",
  "digital_city.boss.phantom": "ፋንተም (የስውር ጥቃት መሪ)",
  "digital_city.boss.ransom_king": "የራንሰምዌር ንጉስ (የመረጃ አጋች)",
  "digital_city.boss.signal_breaker": "የሲግናል አጥፊ (የቴሌኮም አውዳሚ)",
