  "digital_city.radio.squad_follow": "[አልፋ-1] \"ተቀብያለሁ፣ አዛዥ። የማጀቢያ ቦታ ይዘናል!\"",
  "digital_city.radio.squad_defend": "[ብራቮ-2] \"ወሰኑን እየጠበቅን ነው! በመሠረተ ልማቱ ዙሪያ መከላከያ መስርተናል!\"",
  "digital_city.radio.squad_attack": "[አልፋ-1] \"የጠላት ኢላማ ተለይቷል! እየመታን ነው!\"",
  "digital_city.radio.squad_regroup": "[ቡድን] \"ተቀብለናል! ወደ አዛዡ መጋጠሚያ በመመለስ ላይ ነን!\"",
  "digital_city.radio.enemy_spotted": "[ስካውት] \"ማስጠንቀቂያ! የጠላት ሰርጎ ገቦች ወደ ወሰኑ እየቀረቡ ነው!\"",
  "digital_city.radio.enemy_defeated": "[አልፋ-1] \"ጠላት ተደምስሷል! የቦታው ደህንነት ተረጋግጧል!\"",
  "digital_city.radio.under_fire": "[ብራቮ-2] \"ከባድ ተኩስ ከፍተውብናል! የጋሻ ድጋፍ እንፈልጋለን!\"",
  "digital_city.radio.core_attacked": "[ዋና እዝ] \"አስቸኳይ ማስጠንቀቂያ! የእዝ ማዕከሉ እየተመታ ነው! የጥገና ቢከን ያሰማሩ!\"",
  "digital_city.tutorial.step1_action": "ለመንቀሳቀስ [W], [A], [S], ወይም [D] ይጫኑ",
  "digital_city.tutorial.step2_action": "ካሜራውን ለማዞር ማውዙን ያንቀሳቅሱ",
  "digital_city.tutorial.step3_action": "ሰማያዊ ምልክት (ወዳጅ) እና ቀይ ምልክት (ጠላት) መሆናቸውን ይረዱ — ለመቀጠል Space ይጫኑ",
  "digital_city.tutorial.step4_action": "አነጣጥረው በThreat Blaster ለመተኮስ [ግራ-ጠቅ] ያድርጉ",
  "digital_city.tutorial.step5_action": "የFirewall ጋሻን ለማንሳት [ቀኝ-ጠቅ] አድርገው ይያዙ",
  "digital_city.tutorial.step6_action": "የNetwork Pulse ድንጋጤ ማዕበል ለመልቀቅ [Q] ይጫኑ",
  "digital_city.tutorial.step7_action": "የRecovery Beacon የጥገና ማማ ለማሰማራት [E] ይጫኑ",
  "digital_city.tutorial.step8_action": "የቡድን ትዕዛዝ ለመስጠት [F1-F4] ይጫኑ",
