  "device.scope_android_desc": "የተገናኘውን ተንቀሳቃሽ መሳሪያ በAndroid Debug Bridge (ADB) በኩል ይመረምራል። የሲስተም ስሪትን፣ የደህንነት ማሻሻያ ደረጃን፣ የመሳሪያውን ፊርምዌር መለያ፣ የbootloader መቆለፍን፣ የተረጋገጠ ጅማሬን (AVB)፣ የስክሪን መቆለፊያን፣ የውጭ APK ጭነት እገዳን እና የመተግበሪያዎች ደህንነትን ይፈትሻል።",
