  "m4.quiz.desc": "ስለ HTTP ሄደሮች፣ ኩኪዎች እና TLS ያለዎትን እውቀት ይፈትሹ።",
  "m4.quiz.score": "የእርስዎ ውጤት",
  "m4.quiz.q1": "ሰርቨሩ ከHTTP ወደ HTTPS ቅየራ ቢያደርግም፣ HSTS ለምን በጣም አስፈለገ?",
  "m4.quiz.q1_o1": "ጥቃት አድራሹ በክፍት ኔትወርክ ላይ ቅየራው ከመደረጉ በፊት የመጀመሪያውን ጥሪ ሊጠልፍ ይችላል (SSL stripping)።",
  "m4.quiz.q1_o2": "HSTS ፎቶዎች እና ቅጦች በፍጥነት እንዲጫኑ ያደርጋል።",
  "m4.quiz.q1_o3": "HSTS ራሱ የTLS ሰርተፍኬት ይገዛል እንዲሁም ያድሳል።",
  "m4.quiz.q2": "የትኛው የኩኪ ምልክት ነው የይለፍ ቶከን በXSS ጥቃት እንዳይሰረቅ የሚከላከለው?",
  "m4.quiz.q2_o1": "HttpOnly (ጃቫስክሪፕት እንዳያነበው ይከለክላል)።",
  "m4.quiz.q2_o2": "Domain (ኩኪውን በቅርንጫፎች ይገድባል)።",
  "m4.quiz.q2_o3": "Max-Age=3600 (ከአንድ ሰዓት በኋላ ያጠፋል)።",
  "m4.quiz.q3": "ሰርቨሮች ለምን 'Server' እና 'X-Powered-By' ሄደሮችን መደበቅ አለባቸው?",
  "m4.quiz.q3_o1": "አጥቂዎች እና አውቶማቲክ ስካነሮች የሶፍትዌሩን ስሪት በቀላሉ አውቀው ጥቃት እንዳይሰነዝሩ።",
  "m4.quiz.q3_o2": "ዘመናዊ ብሮውዘሮች ከ3 በላይ ሄደሮች ከመጡ ስለሚበላሹ።",
  "m4.quiz.q3_o3": "የፍለጋ ሞተሮች ድረ-ገጹን እንዳያገኙት ለማድረግ።",
  "m4.quiz.q4": "በሁኔታ DS-C ውስጥ፣ ከCHK-02 እስከ CHK-07 ያሉት ነጥቦች ለምን 'አይታወቅም' ተባሉ?",
  "m4.quiz.q4_o1": "የTLS ሰርተፍኬቱ ስላለፈ ብሮውዘሩ ግንኙነቱን በማቋረጡ ምንም የHTTP ሄደሮች አልተገኙም።",
  "m4.quiz.q4_o2": "የድረ-ገጹ ባለቤት ቅዳሜና እሁድ የHTTP ሄደሮችን ስለሚያጠፋ።",
