  "m4.quiz.topic_tls": "TLS እና የትራንስፖርት ደህንነት",
  "m4.quiz.topic_headers": "የመከላከያ HTTP ሄደሮች",
  "m4.quiz.topic_cookies": "የኩኪ ደህንነት ባህሪያት",
