  "academy.rec.weak_phishing": "የማታለያ መልዕክቶች ውጤትዎ ከ80% በታች ነው። ኮርስ 1ን መከለስ አጠራጣሪ አገናኞችን የመለየት አቅምዎን ያጠናክራል።",
  "academy.rec.weak_password": "የይለፍ ቃል ውጤትዎ ከ80% በታች ነው። ኮርስ 2ን መከለስ መለያዎን ያልተፈቀደ የመግቢያ ጥቃት እንዳይደርስበት ይጠብቃል።",
  "academy.rec.weak_privacy": "የግላዊነት ውጤትዎ ከ80% በታች ነው። ኮርስ 3ን መከለስ የግል መረጃዎን ከማህበራዊ ምህንድስና ጥቃቶች ይጠብቃል።",
  "academy.rec.weak_response": "የአደጋ ምላሽ ውጤትዎ ከ80% በታች ነው። ኮርስ 4ን መከለስ ለተፈጠሩ ችግሮች ትክክለኛ ምላሽ እንዲሰጡ ያግዛል።",
  "academy.rec.weak_website": "የድረ-ገጽ ደህንነት ውጤትዎ ከ80% በታች ነው። ኮርስ 5ን መከለስ የድረ-ገጽ መከላከያዎችን ለመረዳት ይረዳል።",
  "academy.rec.review_phishing": "በማታለያ መልዕክቶች ዙሪያ ጥሩ እድገት አለ! አጠራጣሪ የድረ-ገጽ ስሞችን በፍጥነት መከለስ ሙሉ ብቃት ይሰጥዎታል።",
  "academy.rec.review_password": "ጥሩ የይለፍ ቃል ልማድ! ረጅም የይለፍ ቃላትን እና ባለሁለት ደረጃ ማረጋገጫን (MFA) ይከልሱ።",
  "academy.rec.review_privacy": "ጠንካራ የግላዊነት ግንዛቤ! የማህበራዊ ምህንድስና ማታለያ ምሳሌዎችን መከለስ ወደ ከፍተኛ ደረጃ ያደርስዎታል።",
  "academy.rec.review_response": "ጥሩ የአደጋ ምላሽ መሰረት! የኢትዮ ቴሌኮም 994 እና ቴሌብር 127 ሪፖርት መመሪያዎችን ይከልሱ።",
